namespace UA.Facade.Implementation.Student;
public sealed class LifecycleFacade(
 IRepository<UA.Entities.Student> students,IRepository<Batch> batches,IRepository<Section> sections,
 IRepository<AcademicTerm> terms,IRepository<SemesterDrop> drops,IRepository<StudentStatusHistory> statuses,
 IRepository<StudentBatchHistory> placements,IRepository<CourseEquivalence> equivalents,IRepository<CurriculumCourse> curriculum,
 IRepository<MarkComponent> components,IRepository<Course> courses,IRepository<CoursePrerequisite> prerequisites,IRepository<Offering> offerings,IRepository<Enrollment> enrollments,
 IRepository<Result> results,IRepository<Due> dues,IRepository<FeeType> rates,IRepository<PaymentAllocation> payments,
 IRepository<ExamEvent> events,IRepository<ExamSitting> sittings,IRepository<SeatAllocation> seats,IRepository<MarkSubmission> submissions,
 IRepository<ApprovalRecord> approvals,IRepository<Department> departments,IRepository<DocumentRequest> documents,
 IRepository<AuditEntry> audits,IRepository<UserRole> userRoles,IRepository<Role> roles,IRepository<UserAccount> users,
 IRepository<NotificationTemplate> templates,IRepository<Notification> notifications,
 IUnitOfWork work,IUserAccessFacade access,ICurrentUser current,IClock clock,IConfigurationFacade config,
 IFeeClearanceChecker clearance,IDueGenerator generator,IFeeCalculator calculator) : ILifecycleFacade,ILifecycleWarningScan
{
 private int Actor=>current.UserId??throw new ForbiddenException();
 private async Task<UA.Entities.Student> Student(string id,CancellationToken ct)=>await students.FirstAsync(x=>x.StudentId==id,ct)??throw new NotFoundException();
 private async Task<Batch> Batch(int id,CancellationToken ct)=>await batches.FirstAsync(x=>x.BatchId==id,ct)??throw new NotFoundException();
 private async Task<AcademicTerm> Term(int id,CancellationToken ct)=>await terms.FirstAsync(x=>x.TermId==id,ct)??throw new NotFoundException();
 private async Task<bool> Role(int actor,string role,int dept,CancellationToken ct)=>(await access.ForUserAsync(actor,ct)).Assignments.Any(a=>a.RoleName==role&&(!a.Scoped||a.DepartmentId==dept));
 private async Task<bool> Can(string permission,string role,int dept,CancellationToken ct)=>await Role(Actor,role,dept,ct)&&await access.AllowedAsync(Actor,permission,dept,ct);
 private async Task Require(string permission,string role,int dept,CancellationToken ct){if(!await Can(permission,role,dept,ct))throw new ForbiddenException();}
 private async Task Log(string action,string id,string value,CancellationToken ct)=>await audits.AddAsync(new AuditEntry{UserId=Actor,Action=action,EntityName="Student",EntityId=id,NewValue=value,LoggedAt=clock.Now},ct);
 private async Task<DateTime> Limit(UA.Entities.Student s,CancellationToken ct)=>LifecycleRules.Limit((await Batch(s.AdmissionBatchId,ct)).AdmissionYear);
 private async Task<LifecycleRow> Row(UA.Entities.Student s,CancellationToken ct){var d=(await drops.ListAsync(x=>x.StudentId==s.StudentId,ct)).OrderByDescending(x=>x.DropId).FirstOrDefault();return new(s.StudentId,s.FullName,s.DepartmentId,s.Status,await Limit(s,ct),d?.Status??"None",d?.DroppedSemesterNo,d?.TargetBatchId);}
 public async Task<LifecycleRow[]> ListAsync(CancellationToken ct=default){await access.RequireAsync("students.view",ct:ct);var ds=await departments.ListAsync(ct:ct);var ids=new List<int>();foreach(var d in ds)if(await access.AllowedAsync(Actor,"students.view",d.DepartmentId,ct))ids.Add(d.DepartmentId);var rows=new List<LifecycleRow>();foreach(var s in (await students.ListAsync(x=>ids.Contains(x.DepartmentId),ct)).OrderBy(x=>x.StudentId))rows.Add(await Row(s,ct));return rows.ToArray();}
 public async Task<RetakeShortlistRow[]> ShortlistAsync(CancellationToken ct=default){var actor=Actor;var isController=(await access.ForUserAsync(actor,ct)).Assignments.Any(x=>x.RoleName==RoleNames.Controller&&!x.Scoped)&&await access.AllowedAsync(actor,"exams.manage",null,ct);var allowed=new List<int>();foreach(var d in await departments.ListAsync(ct:ct))if(isController||await access.AllowedAsync(actor,"students.view",d.DepartmentId,ct))allowed.Add(d.DepartmentId);if(allowed.Count==0)throw new ForbiddenException();var cs=await courses.ListAsync(ct:ct);var rows=new List<RetakeShortlistRow>();foreach(var s in await students.ListAsync(x=>allowed.Contains(x.DepartmentId)&&x.Status=="Active",ct))foreach(var a in (await Latest(s.StudentId,ct)).Where(Failed))rows.Add(new(s.StudentId,s.FullName,a.Offering.CourseId,cs.Single(x=>x.CourseId==a.Offering.CourseId).Code,a.Enrollment.AttemptNo));return rows.OrderBy(x=>x.Course).ThenBy(x=>x.StudentId).ToArray();}
 public async Task AuditGraduationExportAsync(CancellationToken ct=default){await access.RequireAsync("exports.sensitive",ct:ct);await audits.AddAsync(new AuditEntry{UserId=Actor,Action="Export graduation list",EntityName="Student",EntityId="Graduation",LoggedAt=clock.Now},ct);await work.SaveChangesAsync(ct);}
 private sealed record Attempt(Enrollment Enrollment,Offering Offering,Result Result);
 private async Task<Attempt[]> Latest(string id,CancellationToken ct){var en=await enrollments.ListAsync(x=>x.StudentId==id,ct);var ids=en.Select(x=>x.EnrollmentId).ToArray();var offerIds=en.Select(x=>x.OfferingId).ToArray();var os=await offerings.ListAsync(x=>offerIds.Contains(x.OfferingId),ct);var rs=await results.ListAsync(x=>ids.Contains(x.EnrollmentId)&&x.PublishedAt!=null,ct);return (from r in rs.GroupBy(x=>x.EnrollmentId).Select(g=>g.OrderByDescending(x=>x.VersionNo).First()) join n in en on r.EnrollmentId equals n.EnrollmentId join o in os on n.OfferingId equals o.OfferingId select new Attempt(n,o,r)).GroupBy(a=>a.Offering.CourseId).Select(g=>g.OrderByDescending(a=>a.Enrollment.AttemptNo).ThenByDescending(a=>a.Result.PublishedAt).First()).ToArray();}
 private static bool Failed(Attempt a)=>a.Result.LetterGrade=="F"||a.Result.ResultStatus=="Absent";
 private static bool Passed(Attempt a)=>LifecycleRules.Passed(a.Result.ResultStatus,a.Result.LetterGrade,a.Result.GradePoint);
 private async Task<GraduationCheck> Check(UA.Entities.Student s,Attempt[] latest,CancellationToken ct){var b=await Batch(s.CurrentBatchId,ct);var links=await curriculum.ListAsync(x=>x.CurriculumId==b.CurriculumId,ct);var ids=links.Select(x=>x.CourseId).ToArray();var allIds=ids.Concat(latest.Select(x=>x.Offering.CourseId)).Distinct().ToArray();var cs=await courses.ListAsync(x=>allIds.Contains(x.CourseId),ct);var passed=latest.Where(Passed).Select(x=>x.Offering.CourseId).ToHashSet();var eq=await equivalents.ListAsync(x=>x.StudentId==s.StudentId,ct);var directPassed=passed.ToHashSet();foreach(var x in eq)if(directPassed.Contains(x.OldCourseId))passed.Add(x.NewCourseId);var required=cs.Where(x=>ids.Contains(x.CourseId)).Sum(x=>x.Credits);var earned=cs.Where(x=>ids.Contains(x.CourseId)&&passed.Contains(x.CourseId)).Sum(x=>x.Credits);var cgpa=ExamRules.Gpa(latest.Where(a=>a.Result.ResultStatus is "Normal" or "Absent").Select(a=>(cs.Single(c=>c.CourseId==a.Offering.CourseId).Credits,a.Result.GradePoint)));var reasons=new List<string>();if(ids.Length==0||links.Select(x=>x.SemesterNo).Distinct().Count()!=8||ids.Any(x=>!passed.Contains(x)))reasons.Add("All eight semesters and curriculum courses must be passed.");if(latest.Any(Failed))reasons.Add("Uncleared F or absent result.");if(latest.Any(a=>a.Result.ResultStatus is not ("Normal" or "Absent")))reasons.Add("Unresolved result disposition.");if(cgpa<2)reasons.Add("CGPA below 2.00.");var limit=await Limit(s,ct);if(latest.Any(a=>a.Result.PublishedAt!.Value.Date>limit))reasons.Add("Result published after seven-year limit.");if(!await clearance.IsClearAsync(s.StudentId,null,ct))reasons.Add("Outstanding dues.");if(s.Status!="Active")reasons.Add("Student is not Active.");return new(reasons.Count==0,earned,required,cgpa,reasons.ToArray());}
 public async Task<LifecycleDetails> DetailsAsync(string? id,CancellationToken ct=default){var s=string.IsNullOrWhiteSpace(id)?await students.FirstAsync(x=>x.UserId==Actor,ct)??throw new ForbiddenException():await Student(id,ct);var own=s.UserId==Actor;if(!own&&!await access.AllowedAsync(Actor,"students.view",s.DepartmentId,ct))throw new ForbiddenException();var latest=await Latest(s.StudentId,ct);var cs=await courses.ListAsync(ct:ct);var en=await enrollments.ListAsync(x=>x.StudentId==s.StudentId&&x.EnrollmentType=="Retake"&&x.Status=="Confirmed",ct);var pendingIds=en.Select(x=>x.EnrollmentId).ToArray();var publishedIds=(await results.ListAsync(x=>pendingIds.Contains(x.EnrollmentId)&&x.PublishedAt!=null,ct)).Select(x=>x.EnrollmentId).ToHashSet();en=en.Where(x=>!publishedIds.Contains(x.EnrollmentId)).ToList();var os=await offerings.ListAsync(ct:ct);var backlog=latest.Where(Failed).Select(a=>new BacklogRow(a.Offering.CourseId,cs.Single(c=>c.CourseId==a.Offering.CourseId).Code+" - "+cs.Single(c=>c.CourseId==a.Offering.CourseId).Title,a.Result.LetterGrade,a.Enrollment.AttemptNo,en.Any(n=>os.Any(o=>o.OfferingId==n.OfferingId&&o.CourseId==a.Offering.CourseId))?"Enrolled":"Not enrolled")).ToArray();var ts=await terms.ListAsync(ct:ct);var termIds=ts.Where(t=>t.StartDate.Date<=clock.Today&&t.EndDate.Date>=clock.Today).Select(t=>t.TermId).ToHashSet();var bs=await batches.ListAsync(x=>x.DepartmentId==s.DepartmentId,ct);var junior=bs.Where(x=>x.AdmissionYear>(bs.Single(batch=>batch.BatchId==s.CurrentBatchId)).AdmissionYear).Select(x=>x.BatchId).ToHashSet();var eligible=os.Where(o=>!o.IsSpecialRetake&&termIds.Contains(o.TermId)&&junior.Contains(o.BatchId)&&o.Status!="Closed"&&backlog.Any(a=>a.CourseId==o.CourseId)).Select(o=>new LifecycleOption(o.OfferingId,$"{cs.Single(c=>c.CourseId==o.CourseId).Code} / batch {o.BatchId} / section {o.SectionId}")).ToArray();var b=await Batch(s.CurrentBatchId,ct);var approvedDrop=await drops.FirstAsync(x=>x.StudentId==s.StudentId&&x.Status=="Approved",ct);if(approvedDrop is not null){var target=await batches.FirstAsync(x=>x.DepartmentId==s.DepartmentId&&x.AdmissionYear==b.AdmissionYear+1,ct);if(target is not null)b=target;}var newIds=(await curriculum.ListAsync(x=>x.CurriculumId==b.CurriculumId,ct)).Select(x=>x.CourseId).ToHashSet();var oldIds=latest.Where(Passed).Select(x=>x.Offering.CourseId).ToHashSet();var docs=await documents.ListAsync(x=>x.StudentId==s.StudentId,ct);var dept=s.DepartmentId;return new(await Row(s,ct),backlog,await Check(s,latest,ct),ts.OrderByDescending(t=>t.StartDate).Select(t=>new LifecycleOption(t.TermId,$"{t.Year} / {t.TermNo}")).ToArray(),eligible,cs.Where(c=>oldIds.Contains(c.CourseId)&&!newIds.Contains(c.CourseId)).Select(c=>new LifecycleOption(c.CourseId,c.Code)).ToArray(),cs.Where(c=>newIds.Contains(c.CourseId)&&!oldIds.Contains(c.CourseId)).Select(c=>new LifecycleOption(c.CourseId,c.Code)).ToArray(),docs.Select(d=>new DocumentRequestRow(d.RequestId,d.StudentId,d.RequestType,d.Status,d.RequestedAt,d.DueId)).ToArray(),own,await Can("drop.request",RoleNames.Coordinator,dept,ct),await Can("drop.recommend",RoleNames.Head,dept,ct),await Can("drop.approve",RoleNames.Registrar,dept,ct),await Can("rejoin.place",RoleNames.Coordinator,dept,ct),await Can("equivalence.decide",RoleNames.Head,dept,ct),await Can("graduation.process",RoleNames.Registrar,dept,ct),await Can("retake.enroll",RoleNames.Coordinator,dept,ct),await Can("requests.process",RoleNames.Registrar,dept,ct));}
 private async Task<ApprovalRecord> Approval(string reference,string type,UA.Entities.Student s,string role,int? requestor,CancellationToken ct){var a=await approvals.FirstAsync(x=>x.ReferenceNo==reference&&x.ApprovalType==type,ct)??throw new BusinessRuleException("Record the physical approval first.");var d=await departments.FirstAsync(x=>x.DepartmentId==s.DepartmentId,ct)??throw new NotFoundException();if(a.ApprovalDate.Date>clock.Today||!a.ReferenceNo.StartsWith(d.Code+"-",StringComparison.OrdinalIgnoreCase)||a.ApproverId==requestor||!await Role(a.ApproverId,role,s.DepartmentId,ct)||await approvals.CountAsync(x=>x.SupersedesId==a.ApprovalId,ct)>0||await drops.CountAsync(x=>x.ApprovalId==a.ApprovalId,ct)>0||await equivalents.CountAsync(x=>x.ApprovalId==a.ApprovalId,ct)>0||await enrollments.CountAsync(x=>x.ApprovalId==a.ApprovalId,ct)>0)throw new BusinessRuleException("Invalid, superseded or already-used approval.");return a;}
 private async Task<int> DropTerm(UA.Entities.Student s,AcademicTerm t,CancellationToken ct){int n=LifecycleRules.Semester((await Batch(s.CurrentBatchId,ct)).AdmissionYear,t.Year,t.TermNo);if(s.Status!="Active"||n<2||n>8||clock.Today>t.DropDeadline.Date||clock.Today>t.RegistrationDeadline.Date||clock.Today>await Limit(s,ct))throw new BusinessRuleException("Drop must be requested for an Active student in semesters 2–8, within the drop window.");var os=await offerings.ListAsync(x=>x.TermId==t.TermId,ct);var ids=os.Select(x=>x.OfferingId).ToArray();if(await enrollments.CountAsync(x=>x.StudentId==s.StudentId&&ids.Contains(x.OfferingId),ct)>0)throw new BusinessRuleException("A semester drop must precede registration.");return n;}
 public async Task RequestDropAsync(string id,int termId,CancellationToken ct=default){await work.ExecuteTransactionAsync(async token=>{var s=await Student(id,token);await Require("drop.request",RoleNames.Coordinator,s.DepartmentId,token);var term=await Term(termId,token);var first=(await terms.ListAsync(x=>x.EndDate>=clock.Today,token)).OrderBy(x=>x.StartDate).FirstOrDefault();if(first?.TermId!=termId&&!(first is not null&&term.StartDate>first.EndDate&&(await terms.ListAsync(x=>x.StartDate>first.EndDate,token)).OrderBy(x=>x.StartDate).FirstOrDefault()?.TermId==termId))throw new BusinessRuleException("Select the current or immediately upcoming term.");int n=await DropTerm(s,term,token);if(await drops.CountAsync(x=>x.StudentId==id&&x.Status!="Rejected",token)>0)throw new BusinessRuleException("A semester-drop record already exists.");await drops.AddAsync(new SemesterDrop{StudentId=id,DroppedSemesterNo=(byte)n,RejoinSemesterNo=(byte)n,RequestedOn=clock.Today,RecommendedBy=Actor,Status="Requested"},token);await Log("Request semester drop",id,$"Semester {n}; term {termId}",token);},ct);}
 public async Task RecommendDropAsync(string id,CancellationToken ct=default){await work.ExecuteTransactionAsync(async token=>{var s=await Student(id,token);await Require("drop.recommend",RoleNames.Head,s.DepartmentId,token);var d=await drops.FirstAsync(x=>x.StudentId==id&&x.Status=="Requested",token)??throw new BusinessRuleException("No pending request.");if(d.RecommendedBy==Actor)throw new BusinessRuleException("Cannot recommend your own request.");d.RecommendedBy=Actor;d.Status="Recommended";await Log("Recommend semester drop",id,"Department recommendation recorded",token);},ct);}
 private async Task Status(UA.Entities.Student s,string status,string reason,int? approval,CancellationToken ct){s.Status=status;await statuses.AddAsync(new StudentStatusHistory{StudentId=s.StudentId,Status=status,Reason=reason,EffectiveDate=clock.Today,ChangedBy=Actor,ApprovalId=approval},ct);await Log("Lifecycle status change",s.StudentId,reason+": "+status,ct);}
 public async Task DecideDropAsync(string id,int termId,string reference,CancellationToken ct=default){await work.ExecuteTransactionAsync(async token=>{var s=await Student(id,token);await Require("drop.approve",RoleNames.Registrar,s.DepartmentId,token);var d=await drops.FirstAsync(x=>x.StudentId==id&&x.Status=="Recommended",token)??throw new BusinessRuleException("Department recommendation required.");var t=await Term(termId,token);if(d.RequestedOn>t.DropDeadline||d.DroppedSemesterNo!=LifecycleRules.Semester((await Batch(s.CurrentBatchId,token)).AdmissionYear,t.Year,t.TermNo))throw new BusinessRuleException("Approval must refer to the requested term.");var a=await Approval(reference,"SemesterDrop",s,RoleNames.Registrar,d.RecommendedBy,token);var lastRequest=(await audits.ListAsync(x=>x.EntityName=="Student"&&x.EntityId==id&&x.Action=="Request semester drop",token)).OrderByDescending(x=>x.AuditId).FirstOrDefault();if(lastRequest?.UserId==Actor||a.ApproverId!=Actor||a.ApprovalDate<d.RequestedOn||a.Status is not ("Approved" or "Rejected"))throw new BusinessRuleException("Invalid Registrar decision.");d.ApprovalId=a.ApprovalId;if(a.Status=="Rejected"){d.Status="Rejected";await Log("Reject semester drop",id,reference+"; registration may be rerun by the Coordinator within the registration window",token);return;}await DropTerm(s,t,token);var ds=await dues.ListAsync(x=>x.StudentId==id&&x.TermId==termId&&x.Status!="Reversed"&&x.Status!="Waived",token);foreach(var due in ds){if(due.Status!="Unpaid"||await payments.CountAsync(x=>x.DueId==due.DueId,token)>0)throw new BusinessRuleException("Existing payments require authorized finance resolution before drop.");due.Status="Reversed";}var ev=(await events.ListAsync(x=>x.TermId==termId,token)).Select(x=>x.EventId).ToArray();var si=(await sittings.ListAsync(x=>ev.Contains(x.EventId),token)).Select(x=>x.SittingId).ToArray();if(await seats.CountAsync(x=>x.StudentId==id&&si.Contains(x.SittingId),token)>0)throw new BusinessRuleException("Existing exam seats must be resolved before a pre-registration drop.");var b=await Batch(s.CurrentBatchId,token);d.TargetBatchId=(await batches.FirstAsync(x=>x.DepartmentId==s.DepartmentId&&x.AdmissionYear==b.AdmissionYear+1,token))?.BatchId;d.Status="Approved";await Status(s,"Dropped","Approved semester drop",a.ApprovalId,token);},ct);}
 public async Task RejoinAsync(string id,int termId,CancellationToken ct=default){await work.ExecuteTransactionAsync(async token=>{var s=await Student(id,token);await Require("rejoin.place",RoleNames.Coordinator,s.DepartmentId,token);var d=await drops.FirstAsync(x=>x.StudentId==id&&x.Status=="Approved",token)??throw new BusinessRuleException("No approved drop.");var t=await Term(termId,token);var old=await Batch(s.CurrentBatchId,token);var b=await batches.FirstAsync(x=>x.DepartmentId==s.DepartmentId&&x.AdmissionYear==old.AdmissionYear+1,token)??throw new BusinessRuleException("The immediate junior batch does not exist; student remains Dropped.");if(s.Status!="Dropped"||LifecycleRules.Semester(b.AdmissionYear,t.Year,t.TermNo)!=d.RejoinSemesterNo||clock.Today<t.StartDate||clock.Today>t.RegistrationDeadline||clock.Today>await Limit(s,token))throw new BusinessRuleException("Rejoin only in the junior batch's matching semester and registration window, within the seven-year limit.");var ss=await sections.ListAsync(x=>x.BatchId==b.BatchId,token);var active=await students.ListAsync(x=>x.CurrentBatchId==b.BatchId&&x.Status=="Active",token);var overflowText=await config.ResolveAsync(ConfigKeys.SectionOverflow,s.DepartmentId,termId,token);var overflow=int.TryParse(overflowText,out var v)?v:5;if(overflow<0||overflow>100)throw new BusinessRuleException("Invalid section overflow configuration.");var section=ss.OrderBy(x=>active.Count(a=>a.SectionId==x.SectionId)).ThenBy(x=>x.SectionId).FirstOrDefault(x=>active.Count(a=>a.SectionId==x.SectionId)<x.Capacity+overflow)??throw new BusinessRuleException("Open an additional section before placement.");var links=await curriculum.ListAsync(x=>x.CurriculumId==b.CurriculumId&&x.SemesterNo==d.RejoinSemesterNo,token);var os=await offerings.ListAsync(x=>!x.IsSpecialRetake&&x.TermId==termId&&x.BatchId==b.BatchId&&x.SectionId==section.SectionId&&x.SemesterNo==d.RejoinSemesterNo&&x.Status!="Closed",token);if(links.Count==0||!links.Select(x=>x.CourseId).ToHashSet().SetEquals(os.Select(x=>x.CourseId)))throw new BusinessRuleException("Generate the junior section's complete offerings first.");var history=await placements.FirstAsync(x=>x.StudentId==id&&x.ToDate==null,token)??throw new BusinessRuleException("Missing placement history.");history.ToDate=clock.Today;s.CurrentBatchId=b.BatchId;s.SectionId=section.SectionId;d.TargetBatchId=b.BatchId;d.Status="Rejoined";await placements.AddAsync(new StudentBatchHistory{StudentId=id,BatchId=b.BatchId,SectionId=section.SectionId,FromDate=clock.Today,Reason="Rejoined after approved semester drop",ApprovalId=d.ApprovalId},token);await Status(s,"Active","Rejoined junior batch",d.ApprovalId,token);var recognized=await RejoinCreditRecognition.PassedAsync(id,enrollments,offerings,results,equivalents,termId,token);foreach(var o in os.Where(x=>!recognized.Contains(x.CourseId))){if(await enrollments.CountAsync(x=>x.StudentId==id&&x.OfferingId==o.OfferingId,token)>0)throw new BusinessRuleException("Existing rejoin enrollment.");await enrollments.AddAsync(new Enrollment{StudentId=id,OfferingId=o.OfferingId,EnrollmentType="Regular",AttemptNo=1,Status="Registered"},token);}await work.SaveChangesAsync(token);await generator.GenerateSemesterAsync(id,termId,token);},ct);}
 public async Task EquivalenceAsync(string id,int oldCourseId,int newCourseId,string reference,CancellationToken ct=default){await work.ExecuteTransactionAsync(async token=>{var s=await Student(id,token);await Require("equivalence.decide",RoleNames.Head,s.DepartmentId,token);var drop=await drops.FirstAsync(x=>x.StudentId==id&&(x.Status=="Approved"||x.Status=="Rejoined"),token)??throw new BusinessRuleException("An approved drop is required.");var latest=await Latest(id,token);var b=await Batch(s.CurrentBatchId,token);if(drop.Status=="Approved")b=await batches.FirstAsync(x=>x.DepartmentId==s.DepartmentId&&x.AdmissionYear==b.AdmissionYear+1,token)??throw new BusinessRuleException("Junior batch does not exist.");else{var targetOffers=(await offerings.ListAsync(x=>x.BatchId==b.BatchId&&x.CourseId==newCourseId,token)).Select(x=>x.OfferingId).ToArray();var targetTerms=(await offerings.ListAsync(x=>targetOffers.Contains(x.OfferingId),token)).Select(x=>x.TermId).ToArray();if(await enrollments.CountAsync(x=>x.StudentId==id&&targetOffers.Contains(x.OfferingId),token)>0||await dues.CountAsync(x=>x.StudentId==id&&x.TermId.HasValue&&targetTerms.Contains(x.TermId.Value)&&x.EnrollmentId==null&&x.Status!="Reversed",token)>0)throw new BusinessRuleException("Record equivalence before registration in the target course; existing academic and financial history must not be altered.");}var links=await curriculum.ListAsync(x=>x.CurriculumId==b.CurriculumId,token);if(oldCourseId==newCourseId||!latest.Any(a=>a.Offering.CourseId==oldCourseId&&Passed(a))||links.Any(x=>x.CourseId==oldCourseId)||!links.Any(x=>x.CourseId==newCourseId)||latest.Any(a=>a.Offering.CourseId==newCourseId&&Passed(a))||await equivalents.CountAsync(x=>x.StudentId==id&&(x.OldCourseId==oldCourseId||x.NewCourseId==newCourseId),token)>0)throw new BusinessRuleException("Choose an unmatched passed old course and required junior curriculum course.");var a=await Approval(reference,"CourseEquivalence",s,RoleNames.Head,null,token);if(a.Status!="Approved"||a.ApproverId!=Actor)throw new BusinessRuleException("Department Head approval required.");await equivalents.AddAsync(new CourseEquivalence{StudentId=id,OldCourseId=oldCourseId,NewCourseId=newCourseId,ApprovalId=a.ApprovalId},token);await Log("Approve course equivalence",id,$"{oldCourseId} -> {newCourseId}; {reference}",token);},ct);}
 public async Task GraduateAsync(string id,bool alumni,CancellationToken ct=default){await work.ExecuteTransactionAsync(async token=>{var s=await Student(id,token);await Require("graduation.process",RoleNames.Registrar,s.DepartmentId,token);if(alumni){if(s.Status!="Graduated")throw new BusinessRuleException("Only graduates can become Alumni.");await Status(s,"Alumni","Registrar alumni transition",null,token);return;}var check=await Check(s,await Latest(id,token),token);if(!check.Eligible)throw new BusinessRuleException(string.Join(" ",check.Reasons));await Status(s,"Graduated","All graduation checks passed",null,token);},ct);}
 public async Task DecideLimitAsync(string id,string status,string reference,CancellationToken ct=default){await work.ExecuteTransactionAsync(async token=>{var s=await Student(id,token);await Require("limit.decide",RoleNames.Registrar,s.DepartmentId,token);if(clock.Today<=await Limit(s,token)||s.Status is not ("Active" or "Dropped" or "Suspended")||status is not ("Withdrawn" or "Expelled" or "Suspended")||s.Status==status)throw new BusinessRuleException("Only a student past the seven-year limit may receive an authorized status decision.");var a=await Approval(reference,"StudentStatus",s,RoleNames.Registrar,null,token);if(a.Status!="Approved"||a.ApproverId!=Actor||await statuses.CountAsync(x=>x.ApprovalId==a.ApprovalId,token)>0||await placements.CountAsync(x=>x.ApprovalId==a.ApprovalId,token)>0)throw new BusinessRuleException("Unused Registrar approval required.");await Status(s,status,"Seven-year limit decision",a.ApprovalId,token);},ct);}
 public async Task RetakeAsync(string id,int offeringId,string? reference,string? reason,CancellationToken ct=default){await work.ExecuteTransactionAsync(async token=>{var s=await Student(id,token);await Require("retake.enroll",RoleNames.Coordinator,s.DepartmentId,token);var o=await offerings.FirstAsync(x=>x.OfferingId==offeringId,token)??throw new NotFoundException();var b=await Batch(o.BatchId,token);var t=await Term(o.TermId,token);var c=await courses.FirstAsync(x=>x.CourseId==o.CourseId,token)??throw new NotFoundException();if(o.IsSpecialRetake||s.Status!="Active"||b.DepartmentId!=s.DepartmentId||b.AdmissionYear<=(await Batch(s.CurrentBatchId,token)).AdmissionYear||o.Status=="Closed"||clock.Today<t.StartDate||clock.Today>t.EndDate||clock.Today>await Limit(s,token)||t.EndDate>await Limit(s,token))throw new BusinessRuleException("Choose an active junior offering in the current term, within the limit.");var schemeKey=RetakeSchemeRules.Key(c.CourseType);RetakeSchemeRules.Resolve(await components.ListAsync(x=>x.DepartmentId==s.DepartmentId&&x.CourseType==schemeKey,token),t.StartDate,c.CourseType);var latest=await Latest(id,token);var failure=latest.SingleOrDefault(a=>a.Offering.CourseId==o.CourseId&&Failed(a))??throw new BusinessRuleException("Only latest published F or Absent courses may be retaken.");var os=await offerings.ListAsync(x=>x.TermId==t.TermId,token);var ids=os.Select(x=>x.OfferingId).ToArray();var en=await enrollments.ListAsync(x=>x.StudentId==id&&ids.Contains(x.OfferingId),token);if(!LifecycleRules.CanRetake(en.Count(x=>x.EnrollmentType=="Retake"))||en.Any(x=>os.Single(y=>y.OfferingId==x.OfferingId).CourseId==o.CourseId))throw new BusinessRuleException("Maximum two retakes per term; duplicate course not permitted.");if(await submissions.CountAsync(x=>x.OfferingId==offeringId&&x.Status!="Draft"&&x.Status!="Returned",token)>0)throw new BusinessRuleException("Offering marks already locked.");var final=await events.FirstAsync(x=>x.TermId==t.TermId&&x.EventType=="Final",token);if(final is not null&&(final.Status=="Completed"||clock.Today>=final.StartDate))throw new BusinessRuleException("Register before the final examination begins.");int? approval=null;if(clock.Today>t.RetakeDeadline){if(string.IsNullOrWhiteSpace(reason)||reason.Length>255)throw new BusinessRuleException("Late retake requires a reason.");var a=await Approval(reference??"","RetakeOverride",s,RoleNames.Head,Actor,token);if(a.Status!="Approved"||!await access.AllowedAsync(a.ApproverId,"retake.override",s.DepartmentId,token))throw new BusinessRuleException("Authorized late retake approval required.");approval=a.ApprovalId;}var priorOffers=(await offerings.ListAsync(x=>x.CourseId==o.CourseId,token)).Select(x=>x.OfferingId).ToArray();var pending=await enrollments.ListAsync(x=>x.StudentId==id&&priorOffers.Contains(x.OfferingId)&&x.EnrollmentType=="Retake"&&x.Status=="Confirmed",token);var pendingIds=pending.Select(x=>x.EnrollmentId).ToArray();var publishedIds=(await results.ListAsync(x=>pendingIds.Contains(x.EnrollmentId)&&x.PublishedAt!=null,token)).Select(x=>x.EnrollmentId).ToHashSet();if(pending.Any(x=>!publishedIds.Contains(x.EnrollmentId)))throw new BusinessRuleException("An earlier retake is still awaiting a published result.");if(failure.Enrollment.AttemptNo==byte.MaxValue)throw new BusinessRuleException("Attempt number exceeds schema capacity.");var record=new Enrollment{StudentId=id,OfferingId=offeringId,EnrollmentType="Retake",AttemptNo=(byte)(failure.Enrollment.AttemptNo+1),Status="Confirmed",ApprovalId=approval};await enrollments.AddAsync(record,token);await work.SaveChangesAsync(token);var rate=calculator.Rate(await rates.ListAsync(x=>x.DepartmentId==s.DepartmentId,token),FeeNames.Retake,t.StartDate);var amount=calculator.Calculate(rate.Amount,1);await dues.AddAsync(new Due{StudentId=id,TermId=t.TermId,EnrollmentId=record.EnrollmentId,FeeTypeId=rate.FeeTypeId,Amount=amount,DueDate=t.RetakeDeadline.Date<clock.Today?clock.Today:t.RetakeDeadline,Status=amount==0?"Paid":"Unpaid"},token);var req=await prerequisites.ListAsync(x=>x.CourseId==o.CourseId,token);var warning=req.Any(x=>!latest.Any(a=>a.Offering.CourseId==x.PrerequisiteCourseId&&Passed(a)));await Log("Retake enrollment",id,$"Offering {offeringId}; prerequisite warning {warning}; {reason}",token);},ct);}
 public async Task SpecialRetakeAsync(string id,int courseId,int termId,CancellationToken ct=default){await work.ExecuteTransactionAsync(async token=>{var s=await Student(id,token);await Require("retake.enroll",RoleNames.Coordinator,s.DepartmentId,token);var t=await Term(termId,token);var ev=await events.FirstAsync(x=>x.TermId==termId&&x.EventType=="Special"&&x.Status=="Draft",token)??throw new BusinessRuleException("Controller must create a draft special retake event first.");if(s.Status!="Active"||clock.Today>=ev.StartDate||ev.StartDate>await Limit(s,token))throw new BusinessRuleException("Student or examination date is not eligible.");var latest=await Latest(id,token);var fail=latest.SingleOrDefault(x=>x.Offering.CourseId==courseId&&Failed(x)&&x.Offering.SemesterNo==8)??throw new BusinessRuleException("Only a published final-semester failure is eligible.");var b=await Batch(s.CurrentBatchId,token);if(LifecycleRules.Semester(b.AdmissionYear,t.Year,t.TermNo)<8)throw new BusinessRuleException("Student has not reached the final semester.");var c=await courses.FirstAsync(x=>x.CourseId==courseId,token)??throw new NotFoundException();var key=RetakeSchemeRules.Key(c.CourseType);RetakeSchemeRules.Resolve(await components.ListAsync(x=>x.DepartmentId==s.DepartmentId&&x.CourseType==key,token),t.StartDate,c.CourseType);var termOffers=await offerings.ListAsync(x=>x.TermId==termId,token);var termIds=termOffers.Select(x=>x.OfferingId).ToArray();var existing=await enrollments.ListAsync(x=>x.StudentId==id&&termIds.Contains(x.OfferingId)&&x.EnrollmentType=="Retake",token);if(!LifecycleRules.CanRetake(existing.Count))throw new BusinessRuleException("Maximum two retake courses per term.");var priorIds=(await offerings.ListAsync(x=>x.CourseId==courseId,token)).Select(x=>x.OfferingId).ToArray();var pending=await enrollments.ListAsync(x=>x.StudentId==id&&priorIds.Contains(x.OfferingId)&&x.EnrollmentType=="Retake"&&x.Status=="Confirmed",token);if(pending.Count>0||existing.Any(x=>termOffers.Single(o=>o.OfferingId==x.OfferingId).CourseId==courseId&&termOffers.Single(o=>o.OfferingId==x.OfferingId).IsSpecialRetake))throw new BusinessRuleException("An existing retake for this course prevents duplicate enrollment.");if(fail.Enrollment.AttemptNo==byte.MaxValue)throw new BusinessRuleException("Attempt number exceeds schema capacity.");var o=termOffers.SingleOrDefault(x=>x.IsSpecialRetake&&x.SectionId==s.SectionId&&x.CourseId==courseId);if(o is null){o=new Offering{TermId=termId,BatchId=s.CurrentBatchId,SectionId=s.SectionId,CourseId=courseId,SemesterNo=8,Status="Active",IsSpecialRetake=true};await offerings.AddAsync(o,token);await work.SaveChangesAsync(token);}var en=new Enrollment{StudentId=id,OfferingId=o.OfferingId,EnrollmentType="Retake",AttemptNo=(byte)(fail.Enrollment.AttemptNo+1),Status="Confirmed"};await enrollments.AddAsync(en,token);await work.SaveChangesAsync(token);var rate=calculator.Rate(await rates.ListAsync(x=>x.DepartmentId==s.DepartmentId,token),FeeNames.Retake,t.StartDate);var amount=calculator.Calculate(rate.Amount,1);await dues.AddAsync(new Due{StudentId=id,TermId=termId,EnrollmentId=en.EnrollmentId,FeeTypeId=rate.FeeTypeId,Amount=amount,DueDate=ev.StartDate,Status=amount==0?"Paid":"Unpaid"},token);await Log("Special retake enrollment",id,$"Offering {o.OfferingId}; event {ev.EventId}; attempt {en.AttemptNo}",token);},ct);}
 public async Task<RetakeSchemePage> SchemesAsync(CancellationToken ct=default){var ds=new List<LifecycleOption>();foreach(var d in await departments.ListAsync(ct:ct))if(await Can("retake.override",RoleNames.Head,d.DepartmentId,ct))ds.Add(new(d.DepartmentId,d.Code));if(ds.Count==0)throw new ForbiddenException();return new(ds.ToArray(),(await terms.ListAsync(ct:ct)).OrderByDescending(t=>t.StartDate).Select(t=>new LifecycleOption(t.TermId,$"{t.Year} / {t.TermNo}")).ToArray(),(await courses.ListAsync(ct:ct)).Select(x=>x.CourseType).Where(x=>x!="Theory"&&x.Length<=13).Distinct().OrderBy(x=>x).ToArray());}
 public async Task SaveSchemeAsync(int departmentId,int termId,string type,RetakeComponentInput[] parts,CancellationToken ct=default){await Require("retake.override",RoleNames.Head,departmentId,ct);if(string.IsNullOrWhiteSpace(type)||type=="Theory"||type.Length>13||await courses.CountAsync(x=>x.CourseType==type,ct)==0)throw new BusinessRuleException("Choose a valid non-theory course type.");if(parts is null||parts.Length==0||parts.Length>20||parts.Any(x=>string.IsNullOrWhiteSpace(x.Name)||x.Name.Trim().Length>40||x.Marks<=0||x.Marks>100||decimal.Round(x.Marks,2)!=x.Marks)||parts.Select(x=>x.Name.Trim()).Distinct(StringComparer.OrdinalIgnoreCase).Count()!=parts.Length||parts.Sum(x=>x.Marks)!=100)throw new BusinessRuleException("Unique component names and positive marks totaling 100 are required.");await work.ExecuteTransactionAsync(async token=>{var t=await Term(termId,token);var key=RetakeSchemeRules.Key(type);var old=await components.ListAsync(x=>x.DepartmentId==departmentId&&x.CourseType==key,token);if(old.Any(x=>x.EffectiveFrom>=t.StartDate))throw new BusinessRuleException("Choose a term later than the existing scheme versions.");var ts=(await terms.ListAsync(x=>x.StartDate>=t.StartDate,token)).Select(x=>x.TermId).ToArray();var bs=(await batches.ListAsync(x=>x.DepartmentId==departmentId,token)).Select(x=>x.BatchId).ToArray();var cs=(await courses.ListAsync(x=>x.CourseType==type,token)).Select(x=>x.CourseId).ToArray();var os=(await offerings.ListAsync(x=>ts.Contains(x.TermId)&&bs.Contains(x.BatchId)&&cs.Contains(x.CourseId),token)).Select(x=>x.OfferingId).ToArray();if(await enrollments.CountAsync(x=>os.Contains(x.OfferingId)&&x.EnrollmentType=="Retake",token)>0)throw new BusinessRuleException("A scheme cannot be changed retroactively for existing retake enrollments.");var version=old.Select(x=>x.VersionNo).DefaultIfEmpty(0).Max()+1;foreach(var p in parts)await components.AddAsync(new MarkComponent{DepartmentId=departmentId,CourseType=key,Name=p.Name.Trim(),MaxMarks=p.Marks,IsAttendanceBased=false,VersionNo=version,EffectiveFrom=t.StartDate},token);await audits.AddAsync(new AuditEntry{UserId=Actor,Action="Configure retake scheme",EntityName="MarkComponent",EntityId=departmentId.ToString(),NewValue=$"{type} version {version}; term {termId}",LoggedAt=clock.Now},token);},ct);}
 public async Task RequestDocumentAsync(string type,CancellationToken ct=default){await work.ExecuteTransactionAsync(async token=>{var s=await students.FirstAsync(x=>x.UserId==Actor,token)??throw new ForbiddenException();if(s.Status=="Dropped")throw new BusinessRuleException("No new dues while Dropped.");if(type is not ("Transcript" or "Testimonial" or "Certificate" or "ID card"))throw new BusinessRuleException("Invalid document type.");if(await documents.CountAsync(x=>x.StudentId==s.StudentId&&x.RequestType==type&&x.Status=="Requested",token)>0)throw new BusinessRuleException("A pending request already exists.");if(clock.Today>await Limit(s,token)&&s.Status is not ("Graduated" or "Alumni"))throw new BusinessRuleException("No new dues after the seven-year limit.");var rate=calculator.Rate(await rates.ListAsync(x=>x.DepartmentId==s.DepartmentId,token),type,clock.Today);var amount=calculator.Calculate(rate.Amount,1);var due=new Due{StudentId=s.StudentId,FeeTypeId=rate.FeeTypeId,Amount=amount,DueDate=clock.Today,Status=amount==0?"Paid":"Unpaid"};await dues.AddAsync(due,token);await work.SaveChangesAsync(token);await documents.AddAsync(new DocumentRequest{StudentId=s.StudentId,RequestType=type,Status="Requested",DueId=due.DueId,RequestedAt=clock.Now},token);await Log("Request academic document",s.StudentId,type,token);},ct);}
 public async Task ProcessDocumentAsync(int id,bool issue,CancellationToken ct=default){await work.ExecuteTransactionAsync(async token=>{var d=await documents.FirstAsync(x=>x.RequestId==id&&x.Status=="Requested",token)??throw new NotFoundException();var s=await Student(d.StudentId,token);await Require("requests.process",RoleNames.Registrar,s.DepartmentId,token);var due=await dues.FirstAsync(x=>x.DueId==d.DueId,token)??throw new BusinessRuleException("Missing request due.");if(issue){if(due.Status is not ("Paid" or "Waived"))throw new BusinessRuleException("Document fee must be cleared.");d.Status="Issued";d.IssuedAt=clock.Now;}else{if(due.Status!="Unpaid"||await payments.CountAsync(x=>x.DueId==due.DueId,token)>0)throw new BusinessRuleException("Finance must resolve payments before rejection.");due.Status="Reversed";d.Status="Rejected";}await Log("Process academic document",s.StudentId,$"Request {id}: {d.Status}",token);},ct);}
 public async Task ScanAsync(CancellationToken ct=default){await work.ExecuteTransactionAsync(async token=>{var t=await templates.FirstAsync(x=>x.Code=="student.limit.warning"&&x.IsActive,token);var rejoin=await templates.FirstAsync(x=>x.Code=="student.rejoin.missing"&&x.IsActive,token);var ready=await templates.FirstAsync(x=>x.Code=="student.rejoin.ready"&&x.IsActive,token);var open=await terms.ListAsync(x=>x.StartDate<=clock.Today&&x.RegistrationDeadline>=clock.Today,token);var rs=await roles.ListAsync(x=>x.Name==RoleNames.Head||x.Name==RoleNames.Registrar||x.Name==RoleNames.Coordinator,token);var roleIds=rs.Select(x=>x.RoleId).ToArray();var assigned=await userRoles.ListAsync(x=>roleIds.Contains(x.RoleId),token);var activeUsers=(await users.ListAsync(x=>x.Status=="Active",token)).Select(x=>x.UserId).ToHashSet();var bs=await batches.ListAsync(ct:token);var ss=await students.ListAsync(x=>x.Status=="Active"||x.Status=="Dropped"||x.Status=="Suspended",token);var ds=await drops.ListAsync(x=>x.Status=="Approved",token);var keys=new HashSet<(int,string)>();async Task Queue(int recipient,NotificationTemplate template,string key){if(!activeUsers.Contains(recipient)||!keys.Add((recipient,key))||await notifications.CountAsync(x=>x.RecipientUserId==recipient&&x.EventKey==key,token)>0)return;await notifications.AddAsync(new Notification{RecipientUserId=recipient,TemplateId=template.TemplateId,EventKey=key,Status="Queued",QueuedAt=clock.Now},token);}foreach(var s in ss){var adm=bs.Single(x=>x.BatchId==s.AdmissionBatchId);var lim=LifecycleRules.Limit(adm.AdmissionYear);if(t is not null&&clock.Today.Year==lim.Year)foreach(var a in assigned.Where(a=>rs.Any(r=>r.RoleId==a.RoleId&&(r.Name==RoleNames.Registrar||(r.Name==RoleNames.Head&&a.DepartmentId==s.DepartmentId)))))await Queue(a.UserId,t,$"limit:{s.DepartmentId}:{clock.Today:yyyyMM}");var b=bs.Single(x=>x.BatchId==s.CurrentBatchId);var drop=ds.FirstOrDefault(x=>x.StudentId==s.StudentId);if(rejoin is not null&&s.Status=="Dropped"&&drop is not null&&clock.Today>=drop.RequestedOn.AddYears(1)&&!bs.Any(x=>x.DepartmentId==s.DepartmentId&&x.AdmissionYear==b.AdmissionYear+1))foreach(var a in assigned.Where(a=>rs.Any(r=>r.RoleId==a.RoleId&&r.Name==RoleNames.Registrar)))await Queue(a.UserId,rejoin,$"rejoin:{s.StudentId}:{clock.Today:yyyyMM}");if(ready is not null&&s.Status=="Dropped"&&drop is not null&&clock.Today<=lim){var junior=bs.SingleOrDefault(x=>x.DepartmentId==s.DepartmentId&&x.AdmissionYear==b.AdmissionYear+1);if(junior is not null)foreach(var term in open.Where(t=>LifecycleRules.Semester(junior.AdmissionYear,t.Year,t.TermNo)==drop.RejoinSemesterNo))foreach(var a in assigned.Where(a=>a.DepartmentId==s.DepartmentId&&rs.Any(r=>r.RoleId==a.RoleId&&(r.Name==RoleNames.Coordinator||r.Name==RoleNames.Head))))await Queue(a.UserId,ready,$"rejoinready:{s.StudentId}:{term.TermId}");}}},ct);}
}
